"use client"

import {
  QueryClient,
  QueryClientContext,
  QueryClientProvider,
  type NetworkMode,
  type QueryClientConfig,
  type Register,
} from "@tanstack/react-query"
import { use, useState, type ReactNode } from "react"

function statusOf(error: unknown) {
  const status = typeof error === "object" && error !== null ? (error as { status?: unknown }).status : undefined
  return typeof status === "number" ? status : undefined
}

/** Whether an error is a client error (4xx), read from its `status`: retrying would fail the same way. */
function isClientError(error: unknown) {
  const status = statusOf(error)
  return status !== undefined && status >= 400 && status < 500
}

/**
 * Whether a retry may succeed: a `status` of 408, 425, 429 or 5xx, or a `TypeError` without one, which is how `fetch`
 * reports a network failure. Any other error (a 4xx, a parse error, an IPC or domain error) fails the same way again.
 */
function isTransientError(error: unknown) {
  const status = statusOf(error)
  if (status === undefined) return error instanceof TypeError
  return status === 408 || status === 425 || status === 429 || status >= 500
}

/**
 * The `error` type of the data hooks when none is given: the `defaultError` an app registers with TanStack Query
 * (`declare module "@tanstack/react-query" { interface Register { defaultError: ApiError } }`), else `unknown`. Not
 * TanStack's `Error`: a fetch can reject with anything, and the hooks typed `error` as `unknown` before.
 */
type DefaultServerError = Register extends { defaultError: infer TError } ? TError : unknown

type RetryRule = (failureCount: number, error: unknown) => boolean

type DataClientOptions = {
  /**
   * When a failed read runs again. A number is the retries after a failure that isn't a 4xx (default 2); a function
   * decides alone, from the failures so far and the error: `(failures, error) => failures < 3 && isTransientError(error)`.
   * `false` never retries, as `0` does.
   */
  retry?: number | false | RetryRule
  /** @deprecated Use `retry`. */
  retries?: number
  /** How long a result counts as fresh, in ms. Default 30 s. */
  staleTime?: number
  /**
   * Reloads a stale query when the window gets focus (`"always"`: even a fresh one). Default false: a table doesn't
   * reload because the window got focus. A hook's own `refetchOnWindowFocus` wins.
   */
  refetchOnWindowFocus?: boolean | "always"
  /**
   * Reloads a stale query when the browser fires `online` (`"always"`: even a fresh one). Default as TanStack's: true,
   * but false with `networkMode: "always"`, whose reads never waited for the network.
   */
  refetchOnReconnect?: boolean | "always"
  /** Reloads a stale query when a hook that reads it mounts (`"always"`: even a fresh one). Default true, TanStack's. */
  refetchOnMount?: boolean | "always"
  /** Retry delay in ms, or a function of the failures so far and the error; TanStack's exponential backoff when unset. */
  retryDelay?: number | ((failureCount: number, error: unknown) => number)
  /**
   * When reads and writes may run, for every hook that doesn't set its own. TanStack's default, `"online"`, pauses them
   * after the browser fires `offline` until it fires `online`: a read stays pending without reaching its error state.
   * `"always"` runs them regardless, for a backend the browser's online state says nothing about (Electron IPC,
   * localhost) or an app that shows its own offline UI. `"offlineFirst"` runs the first attempt and pauses retries.
   */
  networkMode?: NetworkMode
}

function retryRule(retry: number | false | RetryRule): RetryRule {
  if (typeof retry === "function") return retry
  if (retry === false) return () => false
  return (failures, error) => !isClientError(error) && failures < retry
}

/**
 * A query client with the registry's defaults: two retries except on a 4xx, 30 s fresh, no refetch on focus.
 * Mutations never retry: a write that failed may still have reached the server.
 * Pass it to your own `QueryClientProvider`, or let `DataProvider` make one.
 */
function createDataClient(options: DataClientOptions = {}): QueryClient {
  const { retries = 2, staleTime = 30_000, refetchOnWindowFocus = false, retryDelay, networkMode } = options
  const { refetchOnReconnect, refetchOnMount } = options
  const mode = networkMode === undefined ? {} : { networkMode }
  const config: QueryClientConfig = {
    defaultOptions: {
      queries: {
        retry: retryRule(options.retry ?? retries),
        staleTime,
        refetchOnWindowFocus,
        ...(refetchOnReconnect === undefined ? {} : { refetchOnReconnect }),
        ...(refetchOnMount === undefined ? {} : { refetchOnMount }),
        ...(retryDelay === undefined ? {} : { retryDelay }),
        ...mode,
      },
      mutations: { retry: false, ...mode },
    },
  }
  return new QueryClient(config)
}

let fallback: QueryClient | undefined

// Security: a server renderer mounts `DataProvider` per request, so no cache outlives it; this shared client is for
// a single-page app.
function fallbackClient() {
  if (!fallback) {
    fallback = createDataClient()
    fallback.mount()
  }
  return fallback
}

/** The app's `QueryClient` when one is provided, else the shared default. */
function useDataClient(): QueryClient {
  return use(QueryClientContext) ?? fallbackClient()
}

type DataProviderProps = {
  /** A client of your own; otherwise the app's, or a new one with `createDataClient` defaults. */
  client?: QueryClient
  options?: DataClientOptions
  children: ReactNode
}

/** Uses the app's `QueryClient` when it has one; otherwise provides one with the registry's defaults. */
function DataProvider({ client, options, children }: DataProviderProps) {
  const existing = use(QueryClientContext)
  const [own] = useState(() => client ?? createDataClient(options))
  if (existing && !client) return children
  return <QueryClientProvider client={client ?? own}>{children}</QueryClientProvider>
}

export { createDataClient, DataProvider, isClientError, isTransientError, useDataClient }
export type { DataClientOptions, DataProviderProps, DefaultServerError, RetryRule }

import {
  notifyManager,
  partialMatchKey,
  type InfiniteData,
  type Query,
  type QueryClient,
  type QueryKey,
} from "@tanstack/react-query"

import { assumeType } from "@/lib/narrow"
import type { PageResult } from "@/lib/page-source"

// Workaround: TanStack's `cancelRefetch` joins a first load, and a read that left before a write may answer with
// the data from before it, so every read in flight is cancelled silently and fetched again by the caller.
function restartInFlight(
  client: QueryClient,
  filters: { queryKey: readonly unknown[]; predicate?: (query: Query) => boolean },
) {
  const inFlight = client.getQueryCache().findAll({ ...filters, fetchStatus: "fetching" })
  for (const query of inFlight) void query.cancel({ silent: true })
  return inFlight
}

function reloadKey(client: QueryClient, key: readonly unknown[], throwOnError = false) {
  return notifyManager.batch(() => {
    const cache = client.getQueryCache()
    const idle = new Set(cache.findAll({ queryKey: key, fetchStatus: "idle" }))
    const restarted = restartInFlight(client, { queryKey: key })
    const done = client.invalidateQueries({ queryKey: key }, { throwOnError })
    for (const query of restarted) query.fetch().catch(() => undefined)
    const refetched = [...idle].filter((query) => query.state.fetchStatus === "fetching")
    return { restarted, refetched, done }
  })
}

/**
 * Invalidates the key, and refetches its shown queries and every read that was in flight, restarted. Resolves once
 * the shown ones have reloaded; with `throwOnError`, rejects with the first failure.
 */
function refreshKey(client: QueryClient, key: readonly unknown[], throwOnError = false): Promise<void> {
  return reloadKey(client, key, throwOnError).done
}

/**
 * What kind of query this is under the source's key. The hooks mark theirs; a query no hook has observed, such as one
 * filled with `setQueryData` or by a resource's `seeds`, is told by the segment after the key, and anything else is a
 * resource.
 */
function queryKind(query: Query, key: readonly unknown[]): "page" | "infinite" | "total" | "resource" {
  const marked = query.meta?.serverData
  const kind = typeof marked === "string" ? marked : query.queryKey[key.length]
  return kind === "page" || kind === "infinite" || kind === "total" ? kind : "resource"
}

/** A page or infinite query's data with each page's rows updated; `undefined` for any other query or no data. */
function mapItems<T>(kind: unknown, data: unknown, update: (items: T[]) => T[]): unknown {
  if (data === undefined) return undefined
  if (kind === "page") {
    // Workaround: TanStack's cache types data as unknown; the hooks store a `PageResult<T>` under a "page" query.
    const page = assumeType<PageResult<T>>(data)
    return { ...page, items: update(page.items) }
  }
  if (kind === "infinite") {
    // Workaround: TanStack's cache types data as unknown; the hooks store pages of `PageResult<T>` under an "infinite" query.
    const infinite = assumeType<InfiniteData<PageResult<T>>>(data)
    return {
      ...infinite,
      pages: infinite.pages.map((page) => ({ ...page, items: update(page.items) })),
    }
  }
  return undefined
}

function updateItems<T>(client: QueryClient, key: readonly unknown[], update: (items: T[]) => T[]) {
  for (const [queryKey, data] of client.getQueriesData<unknown>({ queryKey: key })) {
    const next = mapItems(queryKey[key.length], data, update)
    if (next !== undefined) client.setQueryData(queryKey, next)
  }
}

/**
 * Writes the server's answer where `next` returns data. Each query written has its read in flight cancelled first, so
 * an answer sent before the change can't overwrite it. The rest of the key is marked stale without a request, and a
 * read of it already in flight, which started before the change, starts again without holding the mutation.
 */
async function settleQueries(client: QueryClient, key: readonly unknown[], next: (query: Query) => unknown) {
  const writes = client
    .getQueryCache()
    .findAll({ queryKey: key })
    .map((query) => [query, next(query)] as const)
    .filter(([, data]) => data !== undefined)
  await Promise.all(writes.map(([query]) => client.cancelQueries({ queryKey: query.queryKey, exact: true })))
  for (const [query, data] of writes) client.setQueryData(query.queryKey, data)
  const written = new Set<Query>(writes.map(([query]) => query))
  const rest = (query: Query) => !written.has(query)
  notifyManager.batch(() => {
    void client.invalidateQueries({ queryKey: key, predicate: rest, refetchType: "none" })
    for (const query of restartInFlight(client, { queryKey: key, predicate: rest }))
      query.fetch().catch(() => undefined)
  })
}

type SourcePatch<T, Data = unknown> = {
  /** The rows of every page and infinite query under the key that has data; each page keeps its total. */
  items?: (items: T[]) => T[]
  /**
   * The data of every other query under the key (`useServerQuery`, `useServerResource`), from what it holds, which is
   * `undefined` while its first read is pending. Return `undefined` to leave it alone, as for another id's detail.
   */
  resource?: (current: Data | undefined, queryKey: readonly unknown[]) => Data | undefined
}

type PatchOptions = {
  /**
   * Also reloads the key afterwards, as `useInvalidateSource` does, and resolves once the shown queries have reloaded.
   * Default false: the patch is what the server holds now and nothing new is requested.
   */
  refetch?: boolean
  /**
   * A read in flight under a query the patch writes may answer with the data from before it. `"restart"` (default)
   * starts it again; `"cancel"` stops it and keeps the patch, as a mutation's `settle`. A first read the patch leaves
   * empty restarts either way, or its query would stay pending.
   */
  inFlight?: "restart" | "cancel"
  /**
   * Resolves once every read in the result's `restarted` has settled, following each query through later restarts
   * (another write, an invalidation) to its latest read. Starts no read of its own. Default false.
   */
  awaitRestarted?: boolean
  /** Rejects with the first failure, after its retries, of a read the call awaits: `refetch`'s or `awaitRestarted`'s. */
  throwOnError?: boolean
}

/** What a patch did, by query key, each list in the cache's order. */
type PatchResult = {
  /** The queries the patch wrote data into. */
  written: readonly QueryKey[]
  /**
   * The queries whose read in flight the patch stopped without starting it again (`inFlight: "cancel"`, or a hold's
   * patch): they show the patch and the read's late answer is dropped. With `refetch` a shown one is read again by the
   * reload, so it is in `refetched` too.
   */
  cancelled: readonly QueryKey[]
  /**
   * The queries whose read in flight this call started again: a written query's under `"restart"`, a first read the
   * patch left empty, with `refetch` every read in flight under the key, and under a hold's patch the reads the hold
   * paused that now run. A read that another hold still pauses isn't listed.
   */
  restarted: readonly QueryKey[]
  /** With `refetch`, the queries the reload started a read for that weren't reading before. */
  refetched: readonly QueryKey[]
}

function latestRead(client: QueryClient, query: Query): Promise<void> {
  const cache = client.getQueryCache()
  const errors = query.state.errorUpdateCount
  return new Promise((resolve, reject) => {
    const settled = (removed: boolean) => {
      if (removed) resolve()
      else if (query.state.fetchStatus !== "idle") return false
      else if (query.state.errorUpdateCount > errors) reject(query.state.error)
      else resolve()
      return true
    }
    if (settled(cache.get(query.queryHash) !== query)) return
    const unsubscribe = cache.subscribe((event) => {
      if (event.query === query && settled(event.type === "removed")) unsubscribe()
    })
  })
}

function awaitReads(client: QueryClient, queries: readonly Query[], throwOnError: boolean): Promise<void> {
  return Promise.all(
    queries.map((query) =>
      throwOnError ? latestRead(client, query) : latestRead(client, query).catch(() => undefined),
    ),
  ).then(() => undefined)
}

/**
 * Holds open under a client, by key. A hook's read under one waits for it to end (`pausedRead`); `holdSource` adds and
 * ends them.
 */
type Hold = { key: readonly unknown[]; ended: Promise<void> }

const holds = new WeakMap<QueryClient, Set<Hold>>()
const pausedReads = new WeakMap<Query, number>()

function holdOver(client: QueryClient, queryKey: readonly unknown[]): Hold | undefined {
  for (const hold of holds.get(client) ?? []) if (partialMatchKey(queryKey, hold.key)) return hold
  return undefined
}

/** The query's read is a hook's read waiting for a hold to end, so it hasn't sent a request. */
function isPaused(query: Query) {
  return (pausedReads.get(query) ?? 0) > 0
}

/** The hooks read through `pausedRead`; a query no hook owns (a prefetch) reads without waiting for a hold. */
function knowsHolds(query: Query) {
  return typeof query.meta?.serverData === "string"
}

/**
 * Runs `read` once no hold covers the key; until then the query reads as fetching and nothing is requested. Aborting
 * the signal (the read is cancelled or restarted) drops the wait without a request.
 */
function pausedRead<T>(
  client: QueryClient,
  context: { queryKey: readonly unknown[]; signal: AbortSignal },
  read: () => Promise<T>,
): Promise<T> {
  const hold = holdOver(client, context.queryKey)
  if (hold === undefined) return read()
  const { signal } = context
  const query = client.getQueryCache().find({ queryKey: context.queryKey, exact: true })
  if (query !== undefined) pausedReads.set(query, (pausedReads.get(query) ?? 0) + 1)
  let waiting = true
  const stop = () => {
    if (!waiting) return false
    waiting = false
    if (query !== undefined) pausedReads.set(query, (pausedReads.get(query) ?? 1) - 1)
    return true
  }
  return new Promise<void>((resolve, reject) => {
    const abort = () => {
      if (stop()) reject(signal.reason)
    }
    if (signal.aborted) abort()
    else signal.addEventListener("abort", abort, { once: true })
    void hold.ended.then(() => {
      signal.removeEventListener("abort", abort)
      if (stop()) resolve()
    })
  }).then(() => pausedRead(client, context, read))
}

function keysOf(queries: Iterable<Query>): QueryKey[] {
  return Array.from(queries, (query) => query.queryKey)
}

/**
 * Writes the patch, restarts or cancels the reads it makes stale and reloads with `refetch`. `resume` runs in the
 * write's batch with the queries written, and returns the reads a hold's patch lets run.
 */
function runPatch<T, Data>(
  client: QueryClient,
  key: readonly unknown[],
  patch: SourcePatch<T, Data>,
  options: PatchOptions,
  resume?: (written: ReadonlySet<Query>) => readonly Query[],
): Promise<PatchResult> {
  const refetch = options.refetch === true
  const throwOnError = options.throwOnError === true
  const cancel = options.inFlight === "cancel"
  const written = new Set<Query>()
  const cancelled: Query[] = []
  const stale: Query[] = []
  const resumed = notifyManager.batch(() => {
    for (const query of client.getQueryCache().findAll({ queryKey: key })) {
      const current = query.state.data
      const kind = queryKind(query, key)
      const next =
        kind === "resource"
          ? // Workaround: TanStack's cache types data as unknown; a resource under the source's key holds the patch's `Data`.
            patch.resource?.(assumeType<Data | undefined>(current), query.queryKey)
          : patch.items && mapItems<T>(kind, current, patch.items)
      const fetching = query.state.fetchStatus === "fetching"
      // Workaround: a cancel with `revert` puts the state from before the read back at once (TanStack 5.107 reverts in the
      // retryer's `onCancel`), so the write below lands on a query that isn't fetching and nothing reverts it later.
      if (fetching && next !== undefined && cancel) {
        void query.cancel({ revert: true })
        cancelled.push(query)
      } else if (fetching && (next !== undefined || current === undefined)) stale.push(query)
      if (next !== undefined) {
        client.setQueryData(query.queryKey, next)
        written.add(query)
      }
    }
    // Perf: `refetch` restarts every read in flight under the key just after, so restarting here too would send a request
    // that is aborted at once.
    if (!refetch) {
      for (const query of stale) {
        void query.cancel({ silent: true })
        query.fetch().catch(() => undefined)
      }
    }
    return resume?.(written) ?? []
  })
  const reload = refetch ? reloadKey(client, key, throwOnError) : undefined
  const running = (query: Query) => !(knowsHolds(query) && holdOver(client, query.queryKey) !== undefined)
  const restarted = [...new Set([...(reload?.restarted ?? stale), ...resumed])].filter(running)
  const reads = [
    reload?.done,
    options.awaitRestarted === true ? awaitReads(client, restarted, throwOnError) : undefined,
  ].filter((read) => read !== undefined)
  const result: PatchResult = {
    written: keysOf(written),
    cancelled: keysOf(cancelled),
    restarted: keysOf(restarted),
    refetched: keysOf(reload?.refetched ?? []),
  }
  return Promise.all(reads).then(() => result)
}

/**
 * Writes what the server now holds into every cached query under the key, without a request. A read in flight that
 * could answer with the data from before it (its query is written, or has no data yet) restarts in the same batch,
 * or with `inFlight: "cancel"` a written query's read is cancelled; with `refetch`, the whole key reloads afterwards,
 * and its restart of every read in flight stands in for the patch's. Resolves with what it did.
 */
function patchSource<T, Data = unknown>(
  client: QueryClient,
  source: { key: readonly unknown[] },
  patch: SourcePatch<T, Data>,
  options: PatchOptions = {},
): Promise<PatchResult> {
  return runPatch(client, source.key, patch, options)
}

export {
  holdOver,
  holds,
  isPaused,
  knowsHolds,
  mapItems,
  patchSource,
  pausedRead,
  queryKind,
  refreshKey,
  runPatch,
  settleQueries,
  updateItems,
}
export type { Hold, PatchOptions, PatchResult, SourcePatch }

import { notifyManager, type Query, type QueryClient, type QueryKey } from "@tanstack/react-query"

import {
  holds,
  isPaused,
  knowsHolds,
  runPatch,
  type Hold,
  type PatchOptions,
  type PatchResult,
  type SourcePatch,
} from "@/components/ui/server-data-cache"

/** A hold's patch always cancels the reads in flight of the queries it writes, which started before the answer. */
type HoldPatchOptions = Omit<PatchOptions, "inFlight">

type SourceHold<T, Data = unknown> = {
  /** The queries whose read in flight the hold stopped when it began. */
  readonly cancelled: readonly QueryKey[]
  /** Whether the hold is still open: neither `patch` nor `release` has ended it. */
  readonly active: boolean
  /**
   * Ends the hold and writes the answer, as `patch` with `inFlight: "cancel"`: a written query keeps the patch and its
   * paused read is dropped without a request; every other paused read runs now. After the hold has ended (`release`,
   * or the component that made it unmounted), it still writes, as a plain patch with `inFlight: "cancel"`.
   */
  patch: (changes: SourcePatch<T, Data>, options?: HoldPatchOptions) => Promise<PatchResult>
  /** Ends the hold without writing: every read it paused or stopped runs now. Does nothing once the hold has ended. */
  release: () => void
}

function runAgain(client: QueryClient, query: Query) {
  if (client.getQueryCache().get(query.queryHash) !== query || query.state.fetchStatus !== "idle") return false
  query.fetch().catch(() => undefined)
  return true
}

/**
 * Cancels every read in flight under the key now and pauses the hooks' reads under it, which show as fetching and send
 * nothing, until `hold.patch` writes the caller's own answer or `hold.release` gives up; then the paused reads run,
 * except a written query's.
 */
function holdSource<T, Data = unknown>(client: QueryClient, source: { key: readonly unknown[] }): SourceHold<T, Data> {
  const { key } = source
  let end: (() => void) | undefined
  const hold: Hold = {
    key,
    ended: new Promise<void>((resolve) => {
      end = resolve
    }),
  }
  const open = holds.get(client) ?? new Set<Hold>()
  holds.set(client, open)
  open.add(hold)
  const stopped: Query[] = []
  const cancelled = notifyManager.batch(() => {
    const inFlight = client
      .getQueryCache()
      .findAll({ queryKey: key, fetchStatus: "fetching" })
      .filter((query) => !isPaused(query))
    for (const query of inFlight) {
      if (knowsHolds(query)) {
        void query.cancel({ silent: true })
        query.fetch().catch(() => undefined)
      } else {
        void query.cancel({ revert: true })
        stopped.push(query)
      }
    }
    return inFlight.map((query) => query.queryKey)
  })
  const close = () => {
    if (!open.delete(hold)) return false
    end?.()
    return true
  }
  return {
    cancelled,
    get active() {
      return open.has(hold)
    },
    patch: (changes, options = {}) => {
      const paused = client.getQueryCache().findAll({ queryKey: key, fetchStatus: "fetching" }).filter(isPaused)
      const held = close()
      return runPatch(client, key, changes, { ...options, inFlight: "cancel" }, (written) => {
        if (!held) return []
        const resumed = paused.filter((query) => !written.has(query))
        if (options.refetch !== true) {
          for (const query of stopped) if (!written.has(query) && runAgain(client, query)) resumed.push(query)
        }
        return resumed
      })
    },
    release: () => {
      if (!close()) return
      notifyManager.batch(() => {
        for (const query of stopped) runAgain(client, query)
      })
    },
  }
}

export { holdSource }
export type { HoldPatchOptions, SourceHold }

"use client"

import {
  keepPreviousData,
  useInfiniteQuery,
  useMutation,
  useQuery,
  type InfiniteData,
  type NetworkMode,
  type QueryKey,
} from "@tanstack/react-query"
import { useCallback, useEffect, useState, useSyncExternalStore } from "react"

import { useDataClient, type DefaultServerError } from "@/components/ui/server-data"
import {
  mapItems,
  patchSource,
  pausedRead,
  queryKind,
  refreshKey,
  settleQueries,
  updateItems,
  type PatchOptions,
  type PatchResult,
  type SourcePatch,
} from "@/components/ui/server-data-cache"
import { holdSource, type HoldPatchOptions, type SourceHold } from "@/components/ui/server-data-hold"
import {
  createPageController,
  type PageController,
  type PageControllerOptions,
  type PageControllerState,
} from "@/lib/page-controller"
import { assumeType } from "@/lib/narrow"
import {
  resolveNavigation,
  totalOf,
  type Navigation,
  type NavigationMode,
  type PageRequest,
  type PageResult,
  type PageSource,
  type SortSpec,
  type TotalInfo,
} from "@/lib/page-source"

type ServerStatus = "pending" | "error" | "success"

/** `true` reloads a stale query on the event, `"always"` a fresh one too, `false` never. */
type RefetchTrigger = boolean | "always"

/**
 * When a query reloads on its own, per hook; otherwise the client's (`createDataClient`: no reload on focus, reload a
 * stale query on mount, and on reconnect unless `networkMode` is `"always"`). TanStack reloads a query when any hook that reads it asks to, so a resource
 * that must never reload this way (one whose reads overwrite per-item ETags kept for later writes) says so in
 * `defineResource`, for every screen.
 */
type RefetchOptions = {
  refetchOnWindowFocus?: RefetchTrigger
  refetchOnReconnect?: RefetchTrigger
  refetchOnMount?: RefetchTrigger
}

/** What every reading hook takes besides its request: when a read may run and when it reloads on its own. */
type ReadOptions = RefetchOptions & {
  enabled?: boolean
  /** When a read may run, as `createDataClient`'s `networkMode`; otherwise the client's. */
  networkMode?: NetworkMode
}

type ServerPageOptions = ReadOptions & {
  /** Overrides the navigation `"auto"` picks from the source. */
  navigation?: NavigationMode
}

function networkModeOf(networkMode: NetworkMode | undefined) {
  return networkMode === undefined ? {} : { networkMode }
}

const refetchKeys = ["refetchOnWindowFocus", "refetchOnReconnect", "refetchOnMount"] as const

/** A query's `networkMode` and refetch triggers, the unset ones left out so the client's defaults apply. */
function readOptionsOf(options: ReadOptions): Omit<ReadOptions, "enabled"> {
  const picked: Omit<ReadOptions, "enabled"> = { ...networkModeOf(options.networkMode) }
  for (const name of refetchKeys) if (options[name] !== undefined) picked[name] = options[name]
  return picked
}

type ServerPageState<T, TError = DefaultServerError> = {
  /** The page's rows; while another page loads, the previous page's rows stay here. */
  items: T[]
  result: PageResult<T> | undefined
  status: ServerStatus
  /** A request is in flight, the first one or a refetch. */
  fetching: boolean
  /** The rows shown belong to the previous request while the new one loads. */
  previous: boolean
  total: TotalInfo
  navigation: Navigation
  error: TError | null
  retry: () => void
}

function pageKey<F>(source: PageSource<unknown, F>, request: PageRequest<F>): QueryKey {
  return [...source.key, "page", request.filter, request.sort, request.position, request.size]
}

type ServerTotalState<TError = DefaultServerError> = {
  total: number | undefined
  status: ServerStatus
  fetching: boolean
  error: TError | null
}

const pageMeta = { serverData: "page" }
const infiniteMeta = { serverData: "infinite" }
const totalMeta = { serverData: "total" }

/** The source's own count, as a query of its own (`[...key, "total", filter]`); idle without `fetchTotal`. */
function useServerTotal<T, F, TError = DefaultServerError>(
  source: PageSource<T, F>,
  filter: F,
  options: ReadOptions = {},
): ServerTotalState<TError> {
  const client = useDataClient()
  const fetchTotal = source.fetchTotal
  const query = useQuery<number, TError>(
    {
      queryKey: [...source.key, "total", filter],
      queryFn: (context) =>
        pausedRead(client, context, () =>
          fetchTotal
            ? fetchTotal.call(source, filter, { signal: context.signal })
            : Promise.reject(new TypeError("This source has no `fetchTotal`.")),
        ),
      enabled: fetchTotal !== undefined && options.enabled !== false,
      meta: totalMeta,
      ...readOptionsOf(options),
      placeholderData: keepPreviousData,
    },
    client,
  )
  return { total: query.data, status: query.status, fetching: query.isFetching, error: query.error }
}

/**
 * One page of a source for a request. The rows of the previous request stay while the next loads, a superseded
 * request is aborted through its signal, and `fetchTotal` runs beside it without holding the rows back.
 */
function useServerPage<T, F, TError = DefaultServerError>(
  source: PageSource<T, F>,
  request: PageRequest<F>,
  options: ServerPageOptions = {},
): ServerPageState<T, TError> {
  const client = useDataClient()
  const query = useQuery<PageResult<T>, TError>(
    {
      queryKey: pageKey(source, request),
      queryFn: (context) => pausedRead(client, context, () => source.fetchPage(request, { signal: context.signal })),
      enabled: options.enabled !== false,
      meta: pageMeta,
      ...readOptionsOf(options),
      placeholderData: keepPreviousData,
    },
    client,
  )
  const counted = useServerTotal(source, request.filter, options)
  const result = query.data
  const total = totalOf(result, counted.total)
  const { refetch } = query
  const retry = useCallback(() => {
    void refetch()
  }, [refetch])
  return {
    items: result?.items ?? [],
    result,
    status: query.status,
    fetching: query.isFetching,
    previous: query.isPlaceholderData,
    total,
    navigation: resolveNavigation(source.capabilities, options.navigation, total),
    error: query.error,
    retry,
  }
}

type InfiniteRequest<F> = { filter: F; sort: readonly SortSpec[]; size: number }

type ServerInfiniteState<T, TError = DefaultServerError> = {
  /** Every loaded page's rows, in order. */
  items: T[]
  pages: PageResult<T>[]
  status: ServerStatus
  fetching: boolean
  loadingMore: boolean
  hasMore: boolean
  loadMore: () => Promise<void>
  total: TotalInfo
  error: TError | null
  retry: () => void
}

type PageParam = number | string | null

/** Pages that add up, for load more and infinite scroll: page numbers or cursors, as the source pages. */
function useServerInfinite<T, F, TError = DefaultServerError>(
  source: PageSource<T, F>,
  request: InfiniteRequest<F>,
  options: ReadOptions = {},
): ServerInfiniteState<T, TError> {
  const client = useDataClient()
  const cursorMode = source.capabilities.position === "cursor"
  const query = useInfiniteQuery<PageResult<T>, TError, InfiniteData<PageResult<T>, PageParam>, QueryKey, PageParam>(
    {
      queryKey: [...source.key, "infinite", request.filter, request.sort, request.size],
      queryFn: (context: { queryKey: QueryKey; signal: AbortSignal; pageParam: PageParam }) =>
        pausedRead(client, context, () =>
          source.fetchPage(
            {
              ...request,
              position: cursorMode
                ? { cursor: typeof context.pageParam === "number" ? null : context.pageParam, direction: "forward" }
                : { page: typeof context.pageParam === "number" ? context.pageParam : 1 },
            },
            { signal: context.signal },
          ),
        ),
      initialPageParam: (cursorMode ? null : 1) as PageParam,
      getNextPageParam: (last: PageResult<T>, all: PageResult<T>[]): PageParam | undefined => {
        if (cursorMode) return last.nextCursor ?? undefined
        const total = last.total ?? last.totalEstimate
        const more =
          last.hasMore ?? (total === undefined ? last.items.length >= request.size : all.length * request.size < total)
        return more && last.items.length > 0 ? all.length + 1 : undefined
      },
      enabled: options.enabled !== false,
      meta: infiniteMeta,
      ...readOptionsOf(options),
      placeholderData: keepPreviousData,
    },
    client,
  )
  const counted = useServerTotal(source, request.filter, options)
  const pages = query.data?.pages ?? []
  const { fetchNextPage, refetch, hasNextPage, isFetchingNextPage } = query
  const loadMore = useCallback(async () => {
    if (!hasNextPage || isFetchingNextPage) return
    await fetchNextPage()
  }, [fetchNextPage, hasNextPage, isFetchingNextPage])
  const retry = useCallback(() => {
    void refetch()
  }, [refetch])
  return {
    items: pages.flatMap((page) => page.items),
    pages,
    status: query.status,
    fetching: query.isFetching,
    loadingMore: isFetchingNextPage,
    hasMore: hasNextPage,
    loadMore,
    total: totalOf(pages[0], counted.total),
    error: query.error,
    retry,
  }
}

type InvalidateOptions = {
  /** Rejects with the error when a reload fails, after its retries, so the caller can say so. Default false. */
  throwOnError?: boolean
}

/**
 * Refreshes every query of the source by its key prefix: pages, infinite lists, totals and `useServerQuery`
 * resources under it. The returned function resolves once the shown ones have reloaded; with `throwOnError`, here or
 * per call, a failed reload rejects.
 */
function useInvalidateSource(
  source: { key: readonly unknown[] },
  options: InvalidateOptions = {},
): (call?: InvalidateOptions) => Promise<void> {
  const client = useDataClient()
  const { key } = source
  const throwOnError = options.throwOnError === true
  return useCallback(
    (call?: InvalidateOptions) =>
      refreshKey(client, key, typeof call?.throwOnError === "boolean" ? call.throwOnError : throwOnError),
    [client, key, throwOnError],
  )
}

type Snapshot = [QueryKey, unknown][]

/** `patchSource` bound to the app's client and this source, for a write the app learned of elsewhere. */
function usePatchSource<T, Data = unknown>(
  source: PageSource<T, never> | { key: readonly unknown[] },
): (patch: SourcePatch<T, Data>, options?: PatchOptions) => Promise<PatchResult> {
  const client = useDataClient()
  const { key } = source
  return useCallback(
    (patch: SourcePatch<T, Data>, options?: PatchOptions) => patchSource<T, Data>(client, { key }, patch, options),
    [client, key],
  )
}

/**
 * `holdSource` bound to the app's client and this source: the returned function begins a hold. Every hold this
 * component began and hasn't ended is released when it unmounts, so no read stays paused.
 */
function useHoldSource<T, Data = unknown>(
  source: PageSource<T, never> | { key: readonly unknown[] },
): () => SourceHold<T, Data> {
  const client = useDataClient()
  const { key } = source
  const [open] = useState(() => new Set<SourceHold<T, Data>>())
  useEffect(
    () => () => {
      for (const hold of open) hold.release()
      open.clear()
    },
    [open],
  )
  return useCallback(() => {
    for (const ended of open) if (!ended.active) open.delete(ended)
    const hold = holdSource<T, Data>(client, { key })
    open.add(hold)
    return hold
  }, [client, key, open])
}

type SourceMutationOptions<T, Variables, Result, Data = Result, TError = DefaultServerError> = {
  mutationFn: (variables: Variables) => Promise<Result>
  /** Its queries are refreshed once the mutation settles, unless `settleItems` or `settle` writes the answer. */
  source: PageSource<T, never> | { key: readonly unknown[] }
  /** Opt-in: changes the cached rows at once and restores them if the mutation fails. */
  optimistic?: (items: T[], variables: Variables) => T[]
  /**
   * On success, the rows of every page and infinite query under the key, from the server's answer, in place of the
   * refresh: `(items, saved) => items.map((row) => (row.id === saved.id ? saved : row))`. Each page keeps its total.
   */
  settleItems?: (items: T[], result: Result, variables: Variables) => T[]
  /**
   * On success, the data of every `useServerQuery` under the key, from the server's answer, in place of the refresh.
   * `current` is what that query holds; return `undefined` to leave it alone, as for another id's detail.
   */
  settle?: (
    result: Result,
    variables: Variables,
    current: Data | undefined,
    queryKey: readonly unknown[],
  ) => Data | undefined
  /**
   * Mutations with the same `scope.id`, from this hook or any other, run one at a time in the order they were called,
   * as TanStack's `scope`: the next starts once the one before has settled, its refresh included. A failure doesn't
   * stop the queue.
   */
  scope?: { id: string }
  /** TanStack's `mutationKey`, to find these mutations with `useMutationState` or `client.isMutating`. */
  mutationKey?: readonly unknown[]
  /** When the mutation may run, as `createDataClient`'s `networkMode`; otherwise the client's. */
  networkMode?: NetworkMode
  /**
   * Whether a failed mutation reloads the key, in case part of the change reached the server. Default true; false
   * adds no read to a failed command (`optimistic` rows are still restored).
   */
  refreshOnError?: boolean
  onSuccess?: (result: Result, variables: Variables) => unknown
  onError?: (error: TError, variables: Variables) => unknown
}

type SourceMutationState<Variables, Result, TError = DefaultServerError> = {
  mutate: (variables: Variables) => void
  mutateAsync: (variables: Variables) => Promise<Result>
  status: "idle" | "pending" | "error" | "success"
  pending: boolean
  error: TError | null
  reset: () => void
}

/**
 * A change to the source's data. Its queries refresh afterwards; `optimistic` shows the change before, and
 * `settleItems` and `settle` write the server's answer instead of refreshing.
 */
function useSourceMutation<T, Variables = void, Result = unknown, Data = Result, TError = DefaultServerError>(
  options: SourceMutationOptions<T, Variables, Result, Data, TError>,
): SourceMutationState<Variables, Result, TError> {
  const client = useDataClient()
  const { key } = options.source
  const { settle, settleItems } = options
  const settles = settle !== undefined || settleItems !== undefined
  const refreshOnError = options.refreshOnError !== false
  const mutation = useMutation<Result, TError, Variables, { snapshot: Snapshot } | undefined>(
    {
      mutationFn: options.mutationFn,
      ...(options.scope === undefined ? {} : { scope: options.scope }),
      ...(options.mutationKey === undefined ? {} : { mutationKey: options.mutationKey }),
      ...networkModeOf(options.networkMode),
      onMutate: async (variables) => {
        const optimistic = options.optimistic
        if (!optimistic) return undefined
        await client.cancelQueries({ queryKey: key })
        const snapshot = client.getQueriesData<unknown>({ queryKey: key })
        updateItems<T>(client, key, (items) => optimistic(items, variables))
        return { snapshot }
      },
      onError: (error, variables, context) => {
        for (const [queryKey, data] of context?.snapshot ?? []) client.setQueryData(queryKey, data)
        return options.onError?.(error, variables)
      },
      onSuccess: async (result, variables) => {
        if (settles) {
          await settleQueries(client, key, (query) => {
            const data = query.state.data
            const kind = queryKind(query, key)
            // Workaround: TanStack's cache types data as unknown; a resource under the source's key holds the mutation's `Data`.
            if (kind === "resource")
              return settle?.(result, variables, assumeType<Data | undefined>(data), query.queryKey)
            return settleItems && mapItems<T>(kind, data, (items) => settleItems(items, result, variables))
          })
        }
        return options.onSuccess?.(result, variables)
      },
      onSettled: (_result, error) => {
        const refresh = error === null ? !settles : refreshOnError
        return refresh ? refreshKey(client, key) : undefined
      },
    },
    client,
  )
  return {
    mutate: mutation.mutate,
    mutateAsync: mutation.mutateAsync,
    status: mutation.status,
    pending: mutation.isPending,
    error: mutation.error,
    reset: mutation.reset,
  }
}

/** A page controller for the component's life, its state, and the URL followed while mounted. */
function usePageController<T, F>(
  source: PageSource<T, F>,
  options?: PageControllerOptions<F>,
): { state: PageControllerState<F>; controller: PageController<F> } {
  const [controller] = useState(() => createPageController(source, options))
  const state = useSyncExternalStore(controller.subscribe, controller.getState, controller.getState)
  useEffect(() => controller.connect(), [controller])
  useEffect(() => () => controller.dispose(), [controller])
  return { state, controller }
}

export {
  holdSource,
  pageKey,
  patchSource,
  readOptionsOf,
  useInvalidateSource,
  useHoldSource,
  usePatchSource,
  usePageController,
  useServerInfinite,
  useServerPage,
  useServerTotal,
  useSourceMutation,
}
